// ── Position distribution chart ──────────────────────────────
const posEl = document.getElementById('posDistChart');
const maxPos = Math.max(...POS_BUCKETS.map(b => b.count));
POS_BUCKETS.forEach(b => {
  const pct = Math.round(b.count / maxPos * 100);
  posEl.innerHTML += `
  <div class="pos-bar-row">
    <div class="pos-bar-label">${b.label}</div>
    <div class="pos-bar-track">
      <div class="pos-bar-fill" style="width:${pct}%;background:${b.color};"></div>
    </div>
    <div class="pos-bar-val">${b.count}</div>
  </div>`;
});

// ── Tag bars chart ────────────────────────────────────────────
const tagEl = document.getElementById('tagBarsChart');
const tagEntries = Object.entries(TAG_COUNTS).sort((a,b)=>b[1]-a[1]).slice(0,20);
const maxTag = tagEntries[0][1];
tagEntries.forEach(([tag, cnt]) => {
  const pct = Math.round(cnt / maxTag * 100);
  let kdColor = '#9fc69a';
  tagEl.innerHTML += `
  <div class="tag-bar-row">
    <div class="tag-bar-label" title="${tag}">${tag}</div>
    <div class="tag-bar-track"><div class="tag-bar-fill" style="width:${pct}%"></div></div>
    <div class="tag-bar-val">${cnt}</div>
  </div>`;
});

// ── Tag filter buttons ────────────────────────────────────────
const ALL_TAGS = ["alergologie", "chirurgie", "cévní chirurgie", "dermatologie", "diabetologie", "děti", "endokrinologie", "ergoterapie", "estetická dermatologie", "fyzioterapie", "gastroenterologie", "gynekologie", "imunologie", "interní lékařství", "kardiologie", "kurz první pomoci", "my vitality", "nefrologie", "neurologie", "nutriční terapie", "obecná slova", "oftalmologie", "orl", "ortopedie", "pediatrie", "porodnictví", "praktický lékař", "prevence proti rakovině", "proktologie", "psychiatrie", "psychologie", "příčina", "radiodiagnostika", "rehabilitace", "revmatologie", "sonografie", "sportovní medicína", "stomatologie", "urologie", "viscerální manipulace", "vitamínové infuze", "vyšetření", "zákrok"];
const filtersEl = document.getElementById('tagFilters');
let activeTags = new Set();

filtersEl.innerHTML = `<button class="tag-btn all-btn active" onclick="toggleAll()">Vše</button>`;
ALL_TAGS.forEach(tag => {
  filtersEl.innerHTML += `<button class="tag-btn" onclick="toggleTag(this, '${tag.replace(/'/g,"\'")}')"><span>${tag}</span></button>`;
});

function toggleAll() {
  activeTags.clear();
  document.querySelectorAll('.tag-btn').forEach(b => b.classList.remove('active'));
  document.querySelector('.all-btn').classList.add('active');
  currentPage = 0;
  renderTable();
}

function toggleTag(btn, tag) {
  document.querySelector('.all-btn').classList.remove('active');
  if (activeTags.has(tag)) {
    activeTags.delete(tag);
    btn.classList.remove('active');
  } else {
    activeTags.add(tag);
    btn.classList.add('active');
  }
  if (activeTags.size === 0) document.querySelector('.all-btn').classList.add('active');
  currentPage = 0;
  renderTable();
}

// ── Search ────────────────────────────────────────────────────
document.getElementById('kwSearch').addEventListener('input', () => {
  currentPage = 0;
  renderTable();
});

// ── Sort ─────────────────────────────────────────────────────
let sortCol = 'pos', sortAsc = true;

document.querySelectorAll('.kw-table th[data-col]').forEach(th => {
  th.addEventListener('click', () => {
    const col = th.dataset.col;
    if (col === 't' || col === 'trend') return;
    if (sortCol === col) { sortAsc = !sortAsc; }
    else { sortCol = col; sortAsc = true; }
    document.querySelectorAll('.kw-table th').forEach(h => h.classList.remove('sorted'));
    th.classList.add('sorted');
    th.querySelector('.sort-arrow').textContent = sortAsc ? '↑' : '↓';
    currentPage = 0;
    renderTable();
  });
});

// ── Filter + sort data ────────────────────────────────────────
function getFiltered() {
  const q = document.getElementById('kwSearch').value.toLowerCase().trim();
  let data = KW_DATA;

  if (activeTags.size > 0) {
    data = data.filter(r => r.t.some(t => activeTags.has(t)));
  }
  if (q) {
    data = data.filter(r => r.k.toLowerCase().includes(q));
  }

  // Sort
  data = [...data].sort((a, b) => {
    let av, bv;
    if (sortCol === 'k') { av = a.k.toLowerCase(); bv = b.k.toLowerCase(); }
    else if (sortCol === 'pos') {
      av = a.p[6] === null ? 9999 : a.p[6];
      bv = b.p[6] === null ? 9999 : b.p[6];
    }
    else if (sortCol === 'd') { av = a.d || 0; bv = b.d || 0; }
    else if (sortCol === 's') { av = a.s || 0; bv = b.s || 0; }
    else if (sortCol === 'x') { av = a.x || 0; bv = b.x || 0; }
    else return 0;

    if (av < bv) return sortAsc ? -1 : 1;
    if (av > bv) return sortAsc ? 1 : -1;
    return 0;
  });

  return data;
}

// ── Pagination ────────────────────────────────────────────────
let currentPage = 0;
const PAGE_SIZE = 50;

function changePage(dir) {
  const total = getFiltered().length;
  const maxPage = Math.ceil(total / PAGE_SIZE) - 1;
  currentPage = Math.max(0, Math.min(maxPage, currentPage + dir));
  renderTable();
}

// ── Sparkline ────────────────────────────────────────────────
function sparkline(positions) {
  const vals = positions.filter(p => p !== null);
  if (vals.length < 2) return '<span style="color:var(--ink-faint);font-size:10px;font-family:var(--mono);">—</span>';
  
  const W = 60, H = 22, PAD = 2;
  const min = Math.min(...vals), max = Math.max(...vals);
  const range = max - min || 1;
  
  const pts = positions.map((p, i) => {
    if (p === null) return null;
    const x = PAD + (i / 6) * (W - PAD * 2);
    // Invert: lower position = higher on chart
    const y = PAD + ((p - min) / range) * (H - PAD * 2);
    return [x, y];
  }).filter(Boolean);
  
  if (pts.length < 2) return '<span style="color:var(--ink-faint);font-size:10px;font-family:var(--mono);">—</span>';
  
  const pathD = pts.map((p, i) => (i === 0 ? `M${p[0]},${p[1]}` : `L${p[0]},${p[1]}`)).join(' ');
  const trend = vals[vals.length-1] < vals[0]; // lower position = improvement
  const color = trend ? '#7da977' : '#a88a5c';
  
  return `<svg class="sparkline" width="${W}" height="${H}" viewBox="0 0 ${W} ${H}">
    <path d="${pathD}" fill="none" stroke="${color}" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/>
    <circle cx="${pts[pts.length-1][0]}" cy="${pts[pts.length-1][1]}" r="2" fill="${color}"/>
  </svg>`;
}

// ── Render table ──────────────────────────────────────────────
function renderTable() {
  const filtered = getFiltered();
  const total = filtered.length;
  const maxP = Math.ceil(total / PAGE_SIZE) - 1;
  if (currentPage > maxP) currentPage = Math.max(0, maxP);
  
  const slice = filtered.slice(currentPage * PAGE_SIZE, (currentPage + 1) * PAGE_SIZE);
  
  const tbody = document.getElementById('kwTableBody');
  tbody.innerHTML = '';
  
  slice.forEach(r => {
    const pos = r.p[6];
    let posHtml;
    if (pos === null) {
      posHtml = '<span class="pos-none">—</span>';
    } else if (pos <= 3) {
      posHtml = `<span class="pos-chip pos-top3">${pos}</span>`;
    } else if (pos <= 10) {
      posHtml = `<span class="pos-chip pos-top10">${pos}</span>`;
    } else if (pos <= 20) {
      posHtml = `<span class="pos-chip pos-mid">${pos}</span>`;
    } else {
      posHtml = `<span class="pos-chip pos-low">${pos}</span>`;
    }
    
    const diff = r.d || 0;
    let diffHtml;
    if (diff > 0) diffHtml = `<span class="diff-pos">↑${diff}</span>`;
    else if (diff < 0) diffHtml = `<span class="diff-neg">↓${Math.abs(diff)}</span>`;
    else diffHtml = '<span class="diff-zero">—</span>';
    
    const tags = r.t.slice(0, 3).map(t => `<span class="tag-chip">${t}</span>`).join('');
    
    const sv = r.s ? r.s.toLocaleString('cs-CZ') : '—';
    
    const kdPct = Math.min(100, r.x || 0);
    const kdColor = kdPct <= 30 ? '#7da977' : kdPct <= 60 ? '#a88a5c' : '#c0694a';
    const kdHtml = `<div class="kd-bar-wrap"><div class="kd-bar-bg"><div class="kd-bar-fill" style="width:${kdPct}%;background:${kdColor};"></div></div><div class="kd-val">${r.x || 0}</div></div>`;
    
    tbody.innerHTML += `<tr>
      <td class="kw-cell"><span class="kw-cell-text" title="${r.k}">${r.k}</span></td>
      <td>${tags}</td>
      <td>${posHtml}</td>
      <td class="trend-wrap">${sparkline(r.p)}</td>
      <td>${diffHtml}</td>
      <td class="sv-val">${sv}</td>
      <td>${kdHtml}</td>
    </tr>`;
  });
  
  document.getElementById('resultsCount').innerHTML = `Zobrazeno <strong>${Math.min((currentPage+1)*PAGE_SIZE, total)}</strong> z <strong>${total}</strong> klíčových slov`;
  document.getElementById('pageInfo').textContent = `Strana ${currentPage+1} / ${Math.max(1, Math.ceil(total/PAGE_SIZE))}`;
  document.getElementById('prevBtn').disabled = currentPage === 0;
  document.getElementById('nextBtn').disabled = currentPage >= Math.ceil(total/PAGE_SIZE) - 1;
}

// Init
renderTable();
